import 'dart:io';

class AdHelper {
  // Use test ads during development
  // Replace with your real ad unit IDs before publishing to production
  static const bool _useTesting = true; // Set to false when using real ads

  static String get bannerAdUnitId {
    if (Platform.isAndroid) {
      // For testing: Use Google's test ad unit ID
      if (_useTesting) {
        return 'ca-app-pub-3940256099942544/6300978111'; // Google test banner ad
      }
      // For production: Use your real ad unit ID
      return 'ca-app-pub-2910793143833311/6586681572'; // Your real ad unit ID
    } else if (Platform.isIOS) {
      if (_useTesting) {
        return 'ca-app-pub-3940256099942544/2934735716'; // Google test banner ad
      }
      return 'ca-app-pub-2910793143833311/YOUR_IOS_BANNER_ID'; // Replace with your iOS ad unit ID
    } else {
      throw UnsupportedError('Unsupported platform');
    }
  }


  static String get rewardedAdUnitId {
    if (Platform.isAndroid) {
      // For testing: Use Google's test rewarded ad unit ID
      if (_useTesting) {
        return 'ca-app-pub-3940256099942544/5224354917'; // Google test rewarded ad
      }
      // For production: Use your real ad unit ID
      return 'ca-app-pub-2910793143833311/7209212696'; // Your real rewarded ad unit ID
    } else if (Platform.isIOS) {
      if (_useTesting) {
        return 'ca-app-pub-3940256099942544/1712485313'; // Google test rewarded ad for iOS
      }
      return 'ca-app-pub-2910793143833311/YOUR_IOS_REWARDED_ID'; // Replace with your iOS rewarded ad unit ID
    } else {
      throw UnsupportedError('Unsupported platform');
    }
  }

  static String get interstitialAdUnitId {
    if (Platform.isAndroid) {
      // For testing: Use Google's test interstitial ad unit ID
      if (_useTesting) {
        return 'ca-app-pub-3940256099942544/1033173712'; // Google test interstitial ad
      }
      // For production: Use your real ad unit ID
      return 'ca-app-pub-2910793143833311/YOUR_INTERSTITIAL_ID'; // Your real interstitial ad unit ID
    } else if (Platform.isIOS) {
      if (_useTesting) {
        return 'ca-app-pub-3940256099942544/4411468910'; // Google test interstitial ad for iOS
      }
      return 'ca-app-pub-2910793143833311/YOUR_IOS_INTERSTITIAL_ID'; // Replace with your iOS interstitial ad unit ID
    } else {
      throw UnsupportedError('Unsupported platform');
    }
  }
}

