import 'package:flutter/material.dart';
import 'dart:math' as math;
import 'dart:convert';
import 'package:audioplayers/audioplayers.dart';
import 'package:file_picker/file_picker.dart';
import 'package:google_mobile_ads/google_mobile_ads.dart';
import 'package:applovin_max/applovin_max.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';
import 'setting_screen.dart';
import 'All_song_Store_screen.dart';
import '../../../core/service/shared_preferance/Shared_Preferences.dart';
import '../../../configs/AppConfigs.dart';
import '../controller/ad_helper.dart';
import '../controller/rewarded_ad_manager.dart';

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  double _volume = 50;
  bool _isPlaying = false;
  bool _isPremiumUser = false; 
  BannerAd? _bannerAd;
  final RewardedAdManager _rewardedAdManager = RewardedAdManager();
  late SharedPreferencesService _prefsService;

  // Audio player variables
  AudioPlayer? _audioPlayer;
  Duration _duration = Duration.zero;
  Duration _position = Duration.zero;
  String _currentSongTitle = 'No Song Selected';
  String? _currentSongPath;
  bool _isRepeat = false;
  bool _isShuffle = false;

  // All songs list for skip next/previous
  List<Map<String, String>> _allSongs = [];
  int _currentSongIndex = -1;

  // Track action counts for rewarded ads (show every 3 times)
  int _volumeButtonClickCount = 0;
  int _audioUploadCount = 0;
  static const int _adTriggerFrequency = 3; // Show ad every 3 actions

  // Track actions for showing Remove Ads dialog (every 4 actions)
  int _actionCountForRemoveAds = 0;
  static const int _removeAdsDialogFrequency = 4; // Show Remove Ads dialog every 4 actions

  @override
  void initState() {
    super.initState();
    _initializeServices();
  }

  // Initialize all services
  Future<void> _initializeServices() async {
    // Initialize SharedPreferences service
    _prefsService = await SharedPreferencesService.getInstance();

    // Load premium status and counters
    await _loadPremiumStatus();
    await _loadAdCounters();

    // Initialize audio player
    await _initializeAudioPlayer();

    // Preload rewarded ad for non-premium users
    if (!_isPremiumUser) {
      _rewardedAdManager.loadRewardedAd(
        onAdLoaded: () {
          print(' Rewarded ad ready to show');
        },
        onAdFailedToLoad: (error) {
          print('⚠️ Rewarded ad failed: $error');
        },
      );
    }
  }

  // Load ad counters from SharedPreferences
  Future<void> _loadAdCounters() async {
    final volumeCount = await _prefsService.getVolumeButtonClickCount();
    final audioCount = await _prefsService.getAudioUploadCount();

    setState(() {
      _volumeButtonClickCount = volumeCount;
      _audioUploadCount = audioCount;
    });

    print(' Loaded counters - Volume: $volumeCount, Audio: $audioCount');
  }

  // Load premium status from SharedPreferences
  Future<void> _loadPremiumStatus() async {
    try {
      final isPremium = await _prefsService.isPremiumUser();
      final isPermanent = await _prefsService.isPermanentPremium();
      final hasTemp = await _prefsService.hasTemporaryPremium();

      // Get remaining time if temporary premium
      if (hasTemp) {
        final remaining = await _prefsService.getRemainingPremiumTime();
        if (remaining != null) {
          // Schedule expiry check
          Future.delayed(remaining, () {
            _checkPremiumExpiry();
          });
          print(' Temporary premium expires in: ${remaining.inMinutes} minutes');
        }
      }

      setState(() {
        _isPremiumUser = isPremium;
      });

      if (isPermanent) {
        print(' Premium status loaded: Permanent Premium User');
      } else if (hasTemp) {
        print(' Premium status loaded: Temporary Premium User');
      } else {
        print(' Premium status loaded: Free User');
      }

      // Load banner ad only if not premium
      if (!_isPremiumUser) {
        _loadBannerAd();
      }
    } catch (e) {
      print('❌ Error loading premium status: $e');
      // Load ad anyway if there's an error
      _loadBannerAd();
    }
  }



  void _loadBannerAd() {
    if (!_isPremiumUser) {
      if (AppConfigs.adMobsAd) {
        // Load AdMob Banner Ad
        _loadAdMobBanner();
      } else {
        // Load AppLovin Banner Ad
        _loadAppLovinBanner();
      }
    }
  }

  void _loadAdMobBanner() {
    // Dispose existing ad if any
    _bannerAd?.dispose();
    _bannerAd = null;

    // Add delay to ensure WebView is ready
    Future.delayed(const Duration(milliseconds: 1000), () {
      if (!mounted || _isPremiumUser) return;

      print(' Loading AdMob banner ad...');
      print(' Ad Unit ID: ${AdHelper.bannerAdUnitId}');

      _bannerAd = BannerAd(
        adUnitId: AdHelper.bannerAdUnitId,
        size: AdSize.banner,
        request: const AdRequest(),
        listener: BannerAdListener(
          onAdLoaded: (Ad ad) {
            print('✅ AdMob banner ad loaded successfully');
            if (mounted) {
              setState(() {
                _bannerAd = ad as BannerAd;
              });
            }
          },
          onAdFailedToLoad: (Ad ad, LoadAdError error) {
            print('❌ AdMob banner ad failed to load:');
            print('   Error code: ${error.code}');
            print('   Error domain: ${error.domain}');
            print('   Error message: ${error.message}');

            ad.dispose();

            if (mounted) {
              setState(() {
                _bannerAd = null;
              });

              // Retry loading after 5 seconds
              if (error.code == 2 || error.code == 3 || error.code == 0) {
                print(' Will retry loading AdMob banner ad in 5 seconds...');
                Future.delayed(const Duration(seconds: 5), () {
                  if (mounted && !_isPremiumUser && _bannerAd == null) {
                    _loadAdMobBanner();
                  }
                });
              }
            }
          },
          onAdOpened: (Ad ad) {
            print(' AdMob banner ad opened');
          },
          onAdClosed: (Ad ad) {
            print(' AdMob banner ad closed');
          },
          onAdImpression: (Ad ad) {
            print('️ AdMob banner ad impression recorded');
          },
        ),
      )..load();
    });
  }

  void _loadAppLovinBanner() {
    // AppLovin Banner Ad Implementation
    print(' Loading AppLovin banner ad...');
    print(' Ad Unit ID: ${AdHelper.bannerAdUnitId}');

    AppLovinMAX.createBanner(
      AdHelper.bannerAdUnitId,
      AdViewPosition.bottomCenter,
    );

    AppLovinMAX.setBannerListener(AdViewAdListener(
      onAdLoadedCallback: (ad) {
        print('✅ AppLovin banner ad loaded successfully');
        if (mounted) {
          setState(() {
            // Update UI if needed
          });
        }
      },
      onAdLoadFailedCallback: (adUnitId, error) {
        print('❌ AppLovin banner ad failed to load:');
        print('   Error code: ${error.code}');
        print('   Error message: ${error.message}');

        // Retry after 5 seconds
        Future.delayed(const Duration(seconds: 5), () {
          if (mounted && !_isPremiumUser) {
            _loadAppLovinBanner();
          }
        });
      },
      onAdClickedCallback: (ad) {
        print(' AppLovin banner ad clicked');
      },
      onAdExpandedCallback: (ad) {
        print(' AppLovin banner ad expanded');
      },
      onAdCollapsedCallback: (ad) {
        print(' AppLovin banner ad collapsed');
      },
      onAdRevenuePaidCallback: (ad) {
        print(' AppLovin banner ad revenue paid');
      },
    ));

    AppLovinMAX.showBanner(AdHelper.bannerAdUnitId);
  }

  Future<void> _initializeAudioPlayer() async {
    try {
      _audioPlayer = AudioPlayer();

      // Set player mode for better audio control
      await _audioPlayer!.setPlayerMode(PlayerMode.mediaPlayer);

      // Set audio context for maximum volume control
      await _audioPlayer!.setAudioContext(AudioContext(
        iOS: AudioContextIOS(
          category: AVAudioSessionCategory.playback,
          options: {
            AVAudioSessionOptions.mixWithOthers,
            AVAudioSessionOptions.duckOthers,
          },
        ),
        android: AudioContextAndroid(
          isSpeakerphoneOn: false,
          stayAwake: true,
          contentType: AndroidContentType.music,
          usageType: AndroidUsageType.media,
          audioFocus: AndroidAudioFocus.gain,
        ),
      ));

      // Listen to audio player states
      _audioPlayer!.onDurationChanged.listen((duration) {
        if (mounted) {
          setState(() {
            _duration = duration;
          });
        }
      });

      _audioPlayer!.onPositionChanged.listen((position) {
        if (mounted) {
          setState(() {
            _position = position;
          });
        }
      });

      _audioPlayer!.onPlayerStateChanged.listen((state) {
        if (mounted) {
          setState(() {
            _isPlaying = state == PlayerState.playing;
          });
        }
      });

      _audioPlayer!.onPlayerComplete.listen((event) {
        if (mounted) {
          setState(() {
            _position = Duration.zero;
            _isPlaying = false;
          });

          // Handle repeat mode
          if (_isRepeat) {
            print(' Repeat mode: Restarting audio');
            Future.delayed(const Duration(milliseconds: 300), () {
              _audioPlayer?.seek(Duration.zero);
              _audioPlayer?.resume();
            });
          } else {
            print('✅ Audio completed');
            // Reset to beginning so user can play again
            _audioPlayer?.seek(Duration.zero);
          }
        }
      });

      // Set initial volume - using enhanced boost calculation
      await _applyVolumeBoost(_volume);

      print('Audio player initialized with volume: ${_volume.toInt()}%');
    } catch (e) {
      print('Error initializing audio player: $e');
    }
  }

  @override
  void dispose() {
    _bannerAd?.dispose();
    _rewardedAdManager.dispose();
    _audioPlayer?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF1A1A2E),
      body: SafeArea(
        child: SingleChildScrollView(
          child: Column(
            children: [
              // Banner Ad (shown only for non-premium users)
              if (!_isPremiumUser && _bannerAd != null)
                Container(
                  alignment: Alignment.center,
                  width: _bannerAd!.size.width.toDouble(),
                  height: _bannerAd!.size.height.toDouble(),
                  color: Colors.transparent,
                  child: AdWidget(ad: _bannerAd!),
                ),

            // Header
            Padding(
              padding: EdgeInsets.all(16.w),
              child: Row(
                children: [
                  // IconButton(
                  //   icon: Icon(Icons.menu, color: Colors.white, size: 24.sp),
                  //   onPressed: () async {
                  //     // Navigate to settings and wait for result
                  //     await Navigator.push(
                  //       context,
                  //       MaterialPageRoute(
                  //         builder: (context) => const SettingScreen(),
                  //       ),
                  //     );
                  //
                  //     // Refresh premium status and ads when returning
                  //     await _refreshPremiumStatus();
                  //   },
                  // ),
                  CircleAvatar(
                    radius: 18.r,
                    // backgroundColor: Colors.purple,
                    backgroundImage: AssetImage('assets/images/Volumix-png.png'),
                  ),

                  const Spacer(),
                  Text(
                    'Volume Booster',
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 18.sp,
                      fontWeight: FontWeight.w500,
                    ),
                  ),
                  const Spacer(),
                  IconButton(
                    icon: Icon(Icons.menu, color: Colors.white, size: 24.sp),
                    onPressed: () async {
                      // Navigate to settings and wait for result
                      await Navigator.push(
                        context,
                        MaterialPageRoute(
                          builder: (context) => const SettingScreen(),
                        ),
                      );

                      // Refresh premium status and ads when returning
                      await _refreshPremiumStatus();
                    },
                  ),
                ],
              ),
            ),

            // Navigation Tabs
            Padding(
              padding: EdgeInsets.symmetric(horizontal: 16.w),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceAround,
                children: [
                  _buildTab('Main', true),
                  _buildTab('All Song', false),
                ],
              ),
            ),

            SizedBox(height: 40.h),

            // Main Volume Control with Equalizer Bars
            Container(
              height: 280.h,
              child: Row(
                mainAxisAlignment: MainAxisAlignment.center,
                crossAxisAlignment: CrossAxisAlignment.center,
                children: [
                  // Left Equalizer
                  _buildEqualizerBars(),

                  SizedBox(width: 40.w),

                  // Center Volume Control
                  Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      _buildVolumeKnob(),
                      SizedBox(height: 15.h),
                      Text(
                        'Extra Boost',
                        style: TextStyle(
                          color: Colors.white,
                          fontSize: 15.sp,
                          fontWeight: FontWeight.w400,
                          letterSpacing: 0.5,
                        ),
                      ),
                    ],
                  ),

                  SizedBox(width: 40.w),

                  // Right Equalizer
                  _buildEqualizerBars(),
                ],
              ),
            ),

            // Volume Slider
            Padding(
              padding: EdgeInsets.symmetric(horizontal: 30.w),
              child: Row(
                children: [
                  Icon(Icons.volume_up, color: Colors.cyan, size: 24.sp),
                  Expanded(
                    child: SliderTheme(
                      data: SliderTheme.of(context).copyWith(
                        activeTrackColor: Colors.purple,
                        inactiveTrackColor: Colors.grey[800],
                        thumbColor: Colors.white,
                        overlayColor: Colors.purple.withValues(alpha: 0.2),
                        trackHeight: 4.h,
                      ),
                      child: Slider(
                        value: _volume,
                        min: 0,
                        max: 200,
                        onChanged: (value) async {
                          setState(() {
                            _volume = value;
                          });
                          // Apply volume with boost support (0-200%)
                          await _applyVolumeBoost(_volume);
                        },
                      ),
                    ),
                  ),
                ],
              ),
            ),

            SizedBox(height: 10.h),

            // Volume Percentage Buttons
            Padding(
              padding: EdgeInsets.symmetric(horizontal: 15.w),
              child: Column(
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceAround,
                    children: [
                      _buildPercentageButton('Mute', 0, isPremium: false),
                      _buildPercentageButton('30%', 30, isPremium: false),
                      _buildPercentageButton('60%', 60, isPremium: false),
                      _buildPercentageButton('100%', 100, isPremium: false),
                    ],
                  ),
                  SizedBox(height: 10.h),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceAround,
                    children: [
                      _buildPercentageButton('125%', 125, isPremium: false),
                      _buildPercentageButton('150%', 150, isPremium: true),
                      _buildPercentageButton('175%', 175, isPremium: true),
                      _buildPercentageButton('Max', 200, isPremium: true),
                    ],
                  ),
                ],
              ),
            ),

            SizedBox(height: 30.h),

            // Song Controls
            Container(
              padding: EdgeInsets.symmetric(horizontal: 20.w, vertical: 15.h),
              margin: EdgeInsets.symmetric(horizontal: 20.w),
              decoration: BoxDecoration(
                color: const Color(0xFF16213E),
                borderRadius: BorderRadius.circular(15.r),
              ),
              child: Column(
                children: [
                  // Song Title and Progress Bar
                  Row(
                    children: [
                      Icon(Icons.queue_music, color: Colors.cyan, size: 20.sp),
                      SizedBox(width: 10.w),
                      Expanded(
                        child: Text(
                          _currentSongTitle,
                          style: TextStyle(
                            color: Colors.white,
                            fontSize: 13.sp,
                            fontWeight: FontWeight.w500,
                          ),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                      IconButton(
                        icon: const Icon(Icons.folder_open, color: Colors.white, size: 20),
                        onPressed: _pickAudioFile,
                        padding: EdgeInsets.zero,
                        constraints: const BoxConstraints(),
                      ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  // Progress Slider
                  Row(
                    children: [
                      Text(
                        _formatDuration(_position),
                        style: const TextStyle(
                          color: Colors.grey,
                          fontSize: 11,
                        ),
                      ),
                      Expanded(
                        child: SliderTheme(
                          data: SliderTheme.of(context).copyWith(
                            activeTrackColor: Colors.cyan,
                            inactiveTrackColor: Colors.grey[800],
                            thumbColor: Colors.white,
                            overlayColor: Colors.cyan.withValues(alpha: 0.2),
                            trackHeight: 3,
                            thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 5),
                          ),
                          child: Slider(
                            value: _position.inSeconds.toDouble().clamp(
                              0.0,
                              _duration.inSeconds.toDouble() > 0
                                  ? _duration.inSeconds.toDouble()
                                  : 1.0,
                            ),
                            min: 0,
                            max: _duration.inSeconds.toDouble() > 0
                                ? _duration.inSeconds.toDouble()
                                : 1,
                            onChanged: (value) async {
                              try {
                                if (_currentSongPath != null && _audioPlayer != null && _duration.inSeconds > 0) {
                                  // Clamp the seek position to ensure it's within valid range
                                  final clampedValue = value.clamp(0.0, _duration.inSeconds.toDouble());
                                  final position = Duration(seconds: clampedValue.toInt());

                                  // Only seek if position is valid
                                  if (position.inSeconds < _duration.inSeconds) {
                                    await _audioPlayer?.seek(position);
                                    print('⏩ Seeked to: ${position.inSeconds}s / ${_duration.inSeconds}s');
                                  }
                                }
                              } catch (e) {
                                print('❌ Error seeking: $e');
                              }
                            },
                          ),
                        ),
                      ),
                      Text(
                        _formatDuration(_duration),
                        style: const TextStyle(
                          color: Colors.grey,
                          fontSize: 11,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 5),
                  // Control Buttons
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      IconButton(
                        icon: Icon(
                          Icons.shuffle,
                          color: _isShuffle ? Colors.cyan : Colors.white,
                          size: 20.sp,
                        ),
                        onPressed: () {
                          setState(() {
                            _isShuffle = !_isShuffle;
                          });
                        },
                      ),
                      SizedBox(width: 9.w),
                      IconButton(
                        icon: Icon(Icons.skip_previous, color: Colors.white, size: 28.sp),
                        onPressed: _skipToPrevious,
                      ),
                      SizedBox(width: 9.w),
                      Container(
                        width: 50.w,
                        height: 50.h,
                        decoration: const BoxDecoration(
                          shape: BoxShape.circle,
                          gradient: LinearGradient(
                            colors: [Color(0xFF00D9FF), Color(0xFF0066FF)],
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                          ),
                        ),
                        child: IconButton(
                          icon: Icon(
                            _isPlaying ? Icons.pause : Icons.play_arrow,
                            color: Colors.white,
                            size: 28.sp,
                          ),
                          onPressed: _playPause,
                        ),
                      ),
                      SizedBox(width: 9.w),
                      IconButton(
                        icon: Icon(Icons.skip_next, color: Colors.white, size: 28.sp),
                        onPressed: _skipToNext,
                      ),
                      SizedBox(width: 9.w),
                      IconButton(
                        icon: Icon(
                          Icons.repeat,
                          color: _isRepeat ? Colors.cyan : Colors.white,
                          size: 20.sp,
                        ),
                        onPressed: () {
                          setState(() {
                            _isRepeat = !_isRepeat;
                          });
                        },
                      ),
                    ],
                  ),
                ],
              ),
            ),
            SizedBox(height: 20.h),
          ],
