  Widget _buildEqualizerBars() {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        _buildEqualizerColumn(0),
        const SizedBox(width: 4),
        _buildEqualizerColumn(1),
        const SizedBox(width: 4),
        _buildEqualizerColumn(2),
      ],
    );
  }

  Widget _buildEqualizerColumn(int columnIndex) {
    // Create varying heights for visual effect
    final barHeights = [6.h, 8.h, 6.h][columnIndex];

    return SizedBox(
      height: 200.h,
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        mainAxisSize: MainAxisSize.min,
        children: [
          ...List.generate(
            12, // Reduced from 15 to 12 bars
            (barIndex) {
              Color barColor;
              // Colors from top to bottom: red -> yellow -> green
              if (barIndex < 4) {
                barColor = Colors.red;
              } else if (barIndex < 8) {
                barColor = Colors.yellow;
              } else {
                barColor = Colors.green;
              }

              // Animate bars based on volume - show from bottom to top
              final totalBars = 12;
              final activeBars = (_volume / 200 * totalBars).round();
              final isActive = (totalBars - barIndex) <= activeBars;

              return Container(
                margin: EdgeInsets.symmetric(vertical: 1.5.h),
                width: 8.w,
                height: barHeights,
                decoration: BoxDecoration(
                  color: isActive ? barColor : Colors.grey[850],
                  borderRadius: BorderRadius.circular(1.5.r),
                ),
              );
            },
          ),
        ],
      ),
    );
  }

  Widget _buildPercentageButton(String label, double value, {required bool isPremium}) {
    final isSelected = (_volume - value).abs() < 5;
    final isLocked = isPremium && !_isPremiumUser;

    return InkWell(
      onTap: () async {
        if (isLocked) {
          _showSubscriptionDialog();
        } else {
          // Increment click count for non-premium users
          if (!_isPremiumUser) {
            _volumeButtonClickCount++;
            _actionCountForRemoveAds++;
            print(' Volume button click count: $_volumeButtonClickCount');
            print(' Action count for Remove Ads: $_actionCountForRemoveAds');

            // Show Remove Ads dialog every 4 actions
            if (_actionCountForRemoveAds % _removeAdsDialogFrequency == 0) {
              print(' Showing Remove Ads dialog (every $_removeAdsDialogFrequency actions)');
              _showRemoveAdsDialog();
              return;
            }

            // Show rewarded ad every 3 clicks
            if (_volumeButtonClickCount % _adTriggerFrequency == 0) {
              print(' Triggering rewarded ad (every $_adTriggerFrequency clicks)');
              _showRewardedAdForAction('volume change', () async {
                setState(() {
                  _volume = value;
                });
                await _applyVolumeBoost(_volume);

                if (value > 100) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(' Volume Boost: ${value.toInt()}% - Maximum loudness enabled!'),
                      backgroundColor: Colors.deepOrange,
                      duration: const Duration(milliseconds: 1200),
                    ),
                  );
                }
              });
              return;
            }
          }

          setState(() {
            _volume = value;
          });

          // Apply volume with boost support (0-200%)
          await _applyVolumeBoost(_volume);

          // Show feedback for boost levels
          if (value > 100) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(' Volume Boost: ${value.toInt()}% - Maximum loudness enabled!'),
                backgroundColor: Colors.deepOrange,
                duration: const Duration(milliseconds: 1200),
              ),
            );
          }
        }
      },
      child: Container(
        padding: EdgeInsets.symmetric(horizontal: 12.w, vertical: 8.h),
        decoration: BoxDecoration(
          color: isSelected
              ? Colors.purple.withValues(alpha: 0.3)
              : (isLocked ? Colors.grey[900] : Colors.grey[850]),
          borderRadius: BorderRadius.circular(20.r),
          border: isSelected
              ? Border.all(color: Colors.purple, width: 1.w)
              : (isLocked ? Border.all(color: Colors.orange.withValues(alpha: 0.3), width: 1.w) : null),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (isLocked) ...[
              Icon(
                Icons.lock,
                color: Colors.orange,
                size: 14.sp,
              ),
              SizedBox(width: 4.w),
            ],
            Text(
              label,
              style: TextStyle(
                color: isLocked
                    ? Colors.orange
                    : (isSelected ? Colors.white : Colors.grey[400]),
                fontSize: 12.sp,
                fontWeight: isSelected ? FontWeight.w600 : FontWeight.w400,
              ),
            ),
          ],
        ),
      ),
    );
  }

