class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  double _volume = 50;
  bool _isPlaying = false;
  bool _isPremiumUser = false; 
  BannerAd? _bannerAd;
  final RewardedAdManager _rewardedAdManager = RewardedAdManager();
  late SharedPreferencesService _prefsService;

  // Audio player variables
  AudioPlayer? _audioPlayer;
  Duration _duration = Duration.zero;
  Duration _position = Duration.zero;
  String _currentSongTitle = 'No Song Selected';
  String? _currentSongPath;
  bool _isRepeat = false;
  bool _isShuffle = false;

  // All songs list for skip next/previous
  List<Map<String, String>> _allSongs = [];
  int _currentSongIndex = -1;

  // Track action counts for rewarded ads (show every 3 times)
  int _volumeButtonClickCount = 0;
  int _audioUploadCount = 0;
  static const int _adTriggerFrequency = 3; // Show ad every 3 actions

  // Track actions for showing Remove Ads dialog (every 4 actions)
  int _actionCountForRemoveAds = 0;
  static const int _removeAdsDialogFrequency = 4; // Show Remove Ads dialog every 4 actions

  @override
  void initState() {
    super.initState();
    _initializeServices();
  }

  // Initialize all services
  Future<void> _initializeServices() async {
    // Initialize SharedPreferences service
    _prefsService = await SharedPreferencesService.getInstance();

    // Load premium status and counters
    await _loadPremiumStatus();
    await _loadAdCounters();

    // Initialize audio player
    await _initializeAudioPlayer();

    // Preload rewarded ad for non-premium users
    if (!_isPremiumUser) {
      _rewardedAdManager.loadRewardedAd(
        onAdLoaded: () {
          print(' Rewarded ad ready to show');
        },
        onAdFailedToLoad: (error) {
          print('⚠️ Rewarded ad failed: $error');
        },
      );
    }
  }

  // Load ad counters from SharedPreferences
  Future<void> _loadAdCounters() async {
    final volumeCount = await _prefsService.getVolumeButtonClickCount();
    final audioCount = await _prefsService.getAudioUploadCount();

    setState(() {
      _volumeButtonClickCount = volumeCount;
      _audioUploadCount = audioCount;
    });

    print(' Loaded counters - Volume: $volumeCount, Audio: $audioCount');
  }

  // Load premium status from SharedPreferences
  Future<void> _loadPremiumStatus() async {
    try {
      final isPremium = await _prefsService.isPremiumUser();
      final isPermanent = await _prefsService.isPermanentPremium();
      final hasTemp = await _prefsService.hasTemporaryPremium();

      // Get remaining time if temporary premium
      if (hasTemp) {
        final remaining = await _prefsService.getRemainingPremiumTime();
        if (remaining != null) {
          // Schedule expiry check
          Future.delayed(remaining, () {
            _checkPremiumExpiry();
          });
          print(' Temporary premium expires in: ${remaining.inMinutes} minutes');
        }
      }

      setState(() {
        _isPremiumUser = isPremium;
      });

      if (isPermanent) {
        print(' Premium status loaded: Permanent Premium User');
      } else if (hasTemp) {
        print(' Premium status loaded: Temporary Premium User');
      } else {
        print(' Premium status loaded: Free User');
      }

      // Load banner ad only if not premium
      if (!_isPremiumUser) {
        _loadBannerAd();
      }
    } catch (e) {
      print('❌ Error loading premium status: $e');
      // Load ad anyway if there's an error
      _loadBannerAd();
    }
  }



  void _loadBannerAd() {
    if (!_isPremiumUser) {
      if (AppConfigs.adMobsAd) {
        // Load AdMob Banner Ad
        _loadAdMobBanner();
      } else {
        // Load AppLovin Banner Ad
        _loadAppLovinBanner();
      }
    }
  }

  void _loadAdMobBanner() {
    // Dispose existing ad if any
    _bannerAd?.dispose();
    _bannerAd = null;

    // Add delay to ensure WebView is ready
    Future.delayed(const Duration(milliseconds: 1000), () {
      if (!mounted || _isPremiumUser) return;

      print(' Loading AdMob banner ad...');
      print(' Ad Unit ID: ${AdHelper.bannerAdUnitId}');

      _bannerAd = BannerAd(
        adUnitId: AdHelper.bannerAdUnitId,
        size: AdSize.banner,
        request: const AdRequest(),
        listener: BannerAdListener(
          onAdLoaded: (Ad ad) {
            print('✅ AdMob banner ad loaded successfully');
            if (mounted) {
              setState(() {
                _bannerAd = ad as BannerAd;
              });
            }
          },
          onAdFailedToLoad: (Ad ad, LoadAdError error) {
            print('❌ AdMob banner ad failed to load:');
            print('   Error code: ${error.code}');
            print('   Error domain: ${error.domain}');
            print('   Error message: ${error.message}');

            ad.dispose();

            if (mounted) {
              setState(() {
                _bannerAd = null;
              });

              // Retry loading after 5 seconds
              if (error.code == 2 || error.code == 3 || error.code == 0) {
                print(' Will retry loading AdMob banner ad in 5 seconds...');
                Future.delayed(const Duration(seconds: 5), () {
                  if (mounted && !_isPremiumUser && _bannerAd == null) {
                    _loadAdMobBanner();
                  }
                });
              }
            }
          },
          onAdOpened: (Ad ad) {
            print(' AdMob banner ad opened');
          },
          onAdClosed: (Ad ad) {
            print(' AdMob banner ad closed');
          },
          onAdImpression: (Ad ad) {
            print('️ AdMob banner ad impression recorded');
          },
        ),
      )..load();
    });
  }

  void _loadAppLovinBanner() {
    // AppLovin Banner Ad Implementation
    print(' Loading AppLovin banner ad...');
    print(' Ad Unit ID: ${AdHelper.bannerAdUnitId}');

    AppLovinMAX.createBanner(
      AdHelper.bannerAdUnitId,
      AdViewPosition.bottomCenter,
    );

    AppLovinMAX.setBannerListener(AdViewAdListener(
      onAdLoadedCallback: (ad) {
        print('✅ AppLovin banner ad loaded successfully');
        if (mounted) {
          setState(() {
            // Update UI if needed
          });
        }
      },
      onAdLoadFailedCallback: (adUnitId, error) {
        print('❌ AppLovin banner ad failed to load:');
        print('   Error code: ${error.code}');
        print('   Error message: ${error.message}');

        // Retry after 5 seconds
        Future.delayed(const Duration(seconds: 5), () {
          if (mounted && !_isPremiumUser) {
            _loadAppLovinBanner();
          }
        });
      },
      onAdClickedCallback: (ad) {
        print(' AppLovin banner ad clicked');
      },
      onAdExpandedCallback: (ad) {
        print(' AppLovin banner ad expanded');
      },
      onAdCollapsedCallback: (ad) {
        print(' AppLovin banner ad collapsed');
      },
      onAdRevenuePaidCallback: (ad) {
        print(' AppLovin banner ad revenue paid');
      },
    ));

    AppLovinMAX.showBanner(AdHelper.bannerAdUnitId);
  }

  Future<void> _initializeAudioPlayer() async {
    try {
      _audioPlayer = AudioPlayer();

      // Set player mode for better audio control
      await _audioPlayer!.setPlayerMode(PlayerMode.mediaPlayer);

      // Set audio context for maximum volume control
      await _audioPlayer!.setAudioContext(AudioContext(
        iOS: AudioContextIOS(
          category: AVAudioSessionCategory.playback,
          options: {
            AVAudioSessionOptions.mixWithOthers,
            AVAudioSessionOptions.duckOthers,
          },
        ),
        android: AudioContextAndroid(
          isSpeakerphoneOn: false,
          stayAwake: true,
          contentType: AndroidContentType.music,
          usageType: AndroidUsageType.media,
          audioFocus: AndroidAudioFocus.gain,
        ),
      ));

      // Listen to audio player states
      _audioPlayer!.onDurationChanged.listen((duration) {
        if (mounted) {
          setState(() {
            _duration = duration;
          });
        }
      });

      _audioPlayer!.onPositionChanged.listen((position) {
        if (mounted) {
          setState(() {
            _position = position;
          });
        }
      });

      _audioPlayer!.onPlayerStateChanged.listen((state) {
        if (mounted) {
          setState(() {
            _isPlaying = state == PlayerState.playing;
          });
        }
      });

      _audioPlayer!.onPlayerComplete.listen((event) {
        if (mounted) {
          setState(() {
            _position = Duration.zero;
            _isPlaying = false;
          });

          // Handle repeat mode
          if (_isRepeat) {
            print(' Repeat mode: Restarting audio');
            Future.delayed(const Duration(milliseconds: 300), () {
              _audioPlayer?.seek(Duration.zero);
              _audioPlayer?.resume();
            });
          } else {
            print('✅ Audio completed');
            // Reset to beginning so user can play again
            _audioPlayer?.seek(Duration.zero);
          }
        }
      });

      // Set initial volume - using enhanced boost calculation
      await _applyVolumeBoost(_volume);

      print('Audio player initialized with volume: ${_volume.toInt()}%');
    } catch (e) {
      print('Error initializing audio player: $e');
    }
  }

  @override
  void dispose() {
    _bannerAd?.dispose();
    _rewardedAdManager.dispose();
    _audioPlayer?.dispose();
    super.dispose();
  }

