  // Watch ad for temporary premium
  void _watchAdForTemporaryPremium() async {
    if (!_rewardedAdManager.isAdReady) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Loading ad, please wait...'),
          backgroundColor: Colors.orange,
          duration: Duration(seconds: 2),
        ),
      );

      await _rewardedAdManager.loadRewardedAd(
        onAdLoaded: () {
          _watchAdForTemporaryPremium();
        },
        onAdFailedToLoad: (error) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Failed to load ad: $error'),
              backgroundColor: Colors.red,
            ),
          );
        },
      );
      return;
    }

    await _rewardedAdManager.showRewardedAd(
      onUserEarnedReward: (amount, type) async {
        print(' User earned reward: $amount $type');

        await _prefsService.setTemporaryPremium(const Duration(hours: 1));

        // Dispose banner ad and update UI
        _bannerAd?.dispose();
        setState(() {
          _isPremiumUser = true;
          _bannerAd = null;
        });

        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(' Premium unlocked for 1 hour! Enjoy ad-free experience.'),
            backgroundColor: Colors.green,
            duration: Duration(seconds: 3),
          ),
        );

        print('✅ Temporary premium granted for 1 hour');
      },
      onAdDismissed: () {
        _rewardedAdManager.loadRewardedAd();
      },
    );
  }

  // Show rewarded ad for specific actions (every 3 times)
  void _showRewardedAdForAction(String actionName, Function onComplete) async {
    // Show loading message
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Row(
          children: [
            SizedBox(
              width: 16,
              height: 16,
              child: CircularProgressIndicator(
                strokeWidth: 2,
                valueColor: AlwaysStoppedAnimation<Color>(Colors.white),
              ),
            ),
            SizedBox(width: 16),
            Text('Loading ad...'),
          ],
        ),
        backgroundColor: Colors.blue,
        duration: Duration(seconds: 2),
      ),
    );

    // Check if ad is ready
    if (!_rewardedAdManager.isAdReady) {
      // Ad not ready, try to load it
      await _rewardedAdManager.loadRewardedAd(
        onAdLoaded: () {
          print('✅ Ad loaded for $actionName');
          _showRewardedAdForAction(actionName, onComplete);
        },
        onAdFailedToLoad: (error) {
          print('❌ Ad load failed for $actionName: $error');
          // Allow action anyway if ad fails
          onComplete();
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Ad not available. Continuing...'),
              backgroundColor: Colors.orange,
              duration: Duration(seconds: 2),
            ),
          );
        },
      );
      return;
    }

    // Show the ad directly
    await _rewardedAdManager.showRewardedAd(
      onUserEarnedReward: (amount, type) async {
        print(' User earned reward for $actionName: $amount $type');

        // Execute the action after ad is watched
        await onComplete();

        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Row(
              children: [
                Icon(Icons.check_circle, color: Colors.white),
                SizedBox(width: 10),
                Text('Thanks for watching! '),
              ],
            ),
            backgroundColor: Colors.green,
            duration: Duration(seconds: 2),
          ),
        );
      },
      onAdDismissed: () {
        print('ℹ️ Ad dismissed for $actionName');
        // If user closed ad without completing, still do the action
        onComplete();
        _rewardedAdManager.loadRewardedAd(); // Preload next ad
      },
    );
  }

  // Show rewarded ad for temporary premium access
  void _showRewardedAd() async {
    if (!_rewardedAdManager.isAdReady) {
      // Ad not ready, show loading message
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Row(
            children: [
              CircularProgressIndicator(
                strokeWidth: 2,
                valueColor: AlwaysStoppedAnimation<Color>(Colors.white),
              ),
              SizedBox(width: 16),
              Text('Loading ad, please wait...'),
            ],
          ),
          backgroundColor: Colors.orange,
          duration: Duration(seconds: 2),
        ),
      );

      // Try to load ad
      await _rewardedAdManager.loadRewardedAd(
        onAdLoaded: () {
          print('✅ Rewarded ad loaded, showing now...');
          _showRewardedAd(); // Retry showing ad
        },
        onAdFailedToLoad: (error) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Failed to load ad: $error'),
              backgroundColor: Colors.red,
              duration: const Duration(seconds: 3),
            ),
          );
        },
      );
      return;
    }

    // Show the rewarded ad
    await _rewardedAdManager.showRewardedAd(
      onUserEarnedReward: (amount, type) async {
        print(' User earned reward: $amount $type');

        // Grant temporary premium access (1 hour)
        final prefs = await SharedPreferences.getInstance();
        final expiryTime = DateTime.now().add(const Duration(hours: 1));
        await prefs.setString('temp_premium_expiry', expiryTime.toIso8601String());

        // Dispose banner ad temporarily
        _bannerAd?.dispose();

        setState(() {
          _isPremiumUser = true;
          _bannerAd = null;
        });

        // Show success message
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Row(
              children: [
                Icon(Icons.access_time, color: Colors.white),
                SizedBox(width: 10),
                Expanded(
                  child: Text(
                    ' Premium unlocked for 1 hour! Enjoy ad-free experience.',
                    style: TextStyle(fontSize: 13),
                  ),
                ),
              ],
            ),
            backgroundColor: Colors.green,
            duration: Duration(seconds: 4),
          ),
        );

        // Schedule to check expiry after 1 hour
        Future.delayed(const Duration(hours: 1), () {
          _checkPremiumExpiry();
        });

        print('✅ Temporary premium granted for 1 hour');
      },
      onAdDismissed: () {
        print('ℹ️ Rewarded ad dismissed');
        // Preload next ad
        _rewardedAdManager.loadRewardedAd();
      },
    );
  }

  // Check if temporary premium has expired
  Future<void> _checkPremiumExpiry() async {
    try {
      // Check if temporary premium has expired using service
      final hasTemp = await _prefsService.hasTemporaryPremium();

      if (!hasTemp) {
        // Temporary premium expired, check if user has permanent premium
        final isPermanent = await _prefsService.isPermanentPremium();

        if (!isPermanent) {
          setState(() {
            _isPremiumUser = false;
          });

          // Reload banner ad
          _loadBannerAd();

          // Show notification
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('⏰ Premium trial expired. Watch another ad to continue.'),
                backgroundColor: Colors.orange,
                duration: Duration(seconds: 3),
              ),
            );
          }

          print('⏰ Temporary premium expired');
        }
      }
    } catch (e) {
      print('❌ Error checking premium expiry: $e');
    }
  }

  // Refresh premium status when returning from settings
  Future<void> _refreshPremiumStatus() async {
    try {
      print(' Refreshing premium status...');

      final isPremium = await _prefsService.isPremiumUser();
      final isPermanent = await _prefsService.isPermanentPremium();
      final hasTemp = await _prefsService.hasTemporaryPremium();

      final previousPremiumStatus = _isPremiumUser;

      setState(() {
        _isPremiumUser = isPremium;
      });

      if (isPermanent) {
        print(' Premium status: Permanent Premium User');
      } else if (hasTemp) {
        print(' Premium status: Temporary Premium User');
      } else {
        print(' Premium status: Free User');
      }

      // Handle premium status changes
      if (previousPremiumStatus && !_isPremiumUser) {
        // User removed subscription - load banner ad
        print(' Subscription removed - Loading banner ad...');
        _loadBannerAd();

        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('✅ Subscription removed. You are now a free user.'),
              backgroundColor: Colors.orange,
              duration: Duration(seconds: 3),
            ),
          );
        }
      } else if (!previousPremiumStatus && _isPremiumUser) {
        // User became premium - remove banner ad
        print(' Premium activated - Removing banner ad...');
        _bannerAd?.dispose();
        setState(() {
          _bannerAd = null;
        });

        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text(' Premium activated! Enjoy ad-free experience.'),
              backgroundColor: Colors.green,
              duration: Duration(seconds: 3),
            ),
          );
        }
      } else {
        // Status unchanged - just refresh ads if needed
        if (!_isPremiumUser && _bannerAd == null) {
          print(' Reloading banner ad...');
          _loadBannerAd();
        }
      }

      print('✅ Premium status refreshed');
    } catch (e) {
      print('❌ Error refreshing premium status: $e');
    }
  }

  // Helper method to apply volume with boost
  Future<void> _applyVolumeBoost(double volumePercent) async {
    try {
      double audioVolume;

      // Enhanced volume boost calculation for better loudness at high levels
      if (volumePercent <= 100) {
        // Normal range: 0-100% maps to 0.0-1.0
        audioVolume = volumePercent / 100;
      } else {
        // Boost range: 101-200% maps to 1.0-2.0 with enhanced scaling
        // Using exponential curve for more noticeable boost
        final boostFactor = (volumePercent - 100) / 100; // 0.0 to 1.0
        audioVolume = 1.0 + (boostFactor * 1.0); // 1.0 to 2.0

        // Apply additional platform-specific boost
        // Some platforms support higher values for more aggressive boost
        audioVolume = audioVolume.clamp(0.0, 2.0);
      }

      await _audioPlayer?.setVolume(audioVolume);

      // Also set playback rate slightly higher for boost effect (optional but helps)
      if (volumePercent > 100) {
        // Keep playback rate at 1.0 to avoid pitch change
        await _audioPlayer?.setPlaybackRate(1.0);
      }

      print('✅ Volume applied: ${volumePercent.toInt()}% (audio level: ${audioVolume.toStringAsFixed(2)})');
    } catch (e) {
      print('❌ Error applying volume: $e');
    }
  }

  // Audio Player Methods
  Future<void> _pickAudioFile() async {
    try {
      // Increment upload count for non-premium users
      if (!_isPremiumUser) {
        _audioUploadCount++;
        _actionCountForRemoveAds++;
        print(' Audio upload count: $_audioUploadCount');
        print(' Action count for Remove Ads: $_actionCountForRemoveAds');

        // Show Remove Ads dialog every 4 actions
        if (_actionCountForRemoveAds % _removeAdsDialogFrequency == 0) {
          print(' Showing Remove Ads dialog (every $_removeAdsDialogFrequency actions)');
          _showRemoveAdsDialog();
          return;
        }

        // Show rewarded ad every 3 uploads
        if (_audioUploadCount % _adTriggerFrequency == 0) {
          print(' Triggering rewarded ad (every $_adTriggerFrequency uploads)');
          _showRewardedAdForAction('audio upload', () async {
            await _performAudioFilePick();
          });
          return;
        }
      }

      await _performAudioFilePick();
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error loading audio: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  Future<void> _performAudioFilePick() async {
    try {
      FilePickerResult? result = await FilePicker.platform.pickFiles(
        type: FileType.audio,
      );

      if (result != null && result.files.single.path != null) {
        String filePath = result.files.single.path!;
        String fileName = result.files.single.name;
        String songTitle = fileName.replaceAll(RegExp(r'\.(mp3|wav|m4a|aac)$'), '');

        setState(() {
          _currentSongPath = filePath;
          _currentSongTitle = songTitle;
        });

        await _audioPlayer?.setSourceDeviceFile(filePath);

        // Important: Apply volume boost after loading new audio
        await Future.delayed(const Duration(milliseconds: 100));
        await _applyVolumeBoost(_volume);

        // Save song to storage
        await _saveSongToStorage(songTitle, filePath);

        // Update current song index
        await _loadAllSongs();
        _currentSongIndex = _allSongs.indexWhere((s) => s['path'] == filePath);

        print(' Audio loaded: $fileName with volume boost ${_volume.toInt()}%');
        print(' Current song index: $_currentSongIndex');

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Row(
              children: [
                const Icon(Icons.check_circle, color: Colors.white, size: 20),
                const SizedBox(width: 10),
                Expanded(
                  child: Text('✅ "$songTitle" saved to All Songs'),
                ),
              ],
            ),
            backgroundColor: Colors.green,
            duration: const Duration(seconds: 2),
          ),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error loading audio: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  Future<void> _playPause() async {
    if (_currentSongPath == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please select a song first'),
          backgroundColor: Colors.orange,
          duration: Duration(seconds: 2),
        ),
      );
      return;
    }

    try {
      if (_isPlaying) {
        await _audioPlayer?.pause();
        print('⏸️ Audio paused');
      } else {
        // If audio is at the end, restart from beginning
        if (_position.inSeconds >= _duration.inSeconds && _duration.inSeconds > 0) {
          print(' Audio at end, restarting from beginning');
          await _audioPlayer?.seek(Duration.zero);
        }

        await _audioPlayer?.resume();
        print('▶️ Audio resumed');
      }
    } catch (e) {
      print('❌ Error playing/pausing audio: $e');
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error controlling playback: ${e.toString()}'),
          backgroundColor: Colors.red,
          duration: const Duration(seconds: 2),
        ),
      );
    }
  }

  Future<void> _skipToPrevious() async {
    try {
      // Load all songs from storage
      await _loadAllSongs();

      if (_allSongs.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('⚠️ No songs in library. Upload songs first!'),
            backgroundColor: Colors.orange,
            duration: Duration(seconds: 2),
          ),
        );
        return;
      }

      // If no song is currently playing, play the last song
      if (_currentSongIndex == -1) {
        _currentSongIndex = _allSongs.length - 1;
      } else {
        // Go to previous song
        _currentSongIndex--;
        if (_currentSongIndex < 0) {
          _currentSongIndex = _allSongs.length - 1; // Loop to last song
        }
      }

      // Play the previous song
      final previousSong = _allSongs[_currentSongIndex];
      await _playSongFromStore(previousSong);

      print('⏮️ Playing previous song: ${previousSong['title']} (Index: $_currentSongIndex)');
    } catch (e) {
      print('❌ Error skipping to previous: $e');
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error playing previous song: ${e.toString()}'),
          backgroundColor: Colors.red,
          duration: const Duration(seconds: 2),
        ),
      );
    }
  }

  Future<void> _skipToNext() async {
    try {
      // Load all songs from storage
      await _loadAllSongs();

      if (_allSongs.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('⚠️ No songs in library. Upload songs first!'),
            backgroundColor: Colors.orange,
            duration: Duration(seconds: 2),
          ),
        );
        return;
      }

      // If no song is currently playing, play the first song
      if (_currentSongIndex == -1) {
        _currentSongIndex = 0;
      } else {
        // Go to next song
        _currentSongIndex++;
        if (_currentSongIndex >= _allSongs.length) {
          _currentSongIndex = 0; // Loop to first song
        }
      }

      // Play the next song
      final nextSong = _allSongs[_currentSongIndex];
      await _playSongFromStore(nextSong);

      print('⏭️ Playing next song: ${nextSong['title']} (Index: $_currentSongIndex)');
    } catch (e) {
      print('❌ Error skipping to next: $e');
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error playing next song: ${e.toString()}'),
          backgroundColor: Colors.red,
          duration: const Duration(seconds: 2),
        ),
      );
    }
  }

  // Load all songs from SharedPreferences
  Future<void> _loadAllSongs() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final songsJson = prefs.getString('stored_songs') ?? '[]';
      final List<dynamic> decodedSongs = json.decode(songsJson);

      _allSongs = decodedSongs.map((song) => Map<String, String>.from(song)).toList();

      // Find current song index if a song is playing
      if (_currentSongPath != null) {
        _currentSongIndex = _allSongs.indexWhere((song) => song['path'] == _currentSongPath);
      }

      print(' Loaded ${_allSongs.length} songs, current index: $_currentSongIndex');
    } catch (e) {
      print('❌ Error loading songs: $e');
      _allSongs = [];
      _currentSongIndex = -1;
    }
  }

  // Save song to SharedPreferences storage
  Future<void> _saveSongToStorage(String title, String path) async {
    try {
      final prefs = await SharedPreferences.getInstance();

      // Get existing songs
      final songsJson = prefs.getString('stored_songs') ?? '[]';
      final List<dynamic> songs = json.decode(songsJson);

      // Check if song already exists
      bool alreadyExists = songs.any((song) => song['path'] == path);

      if (!alreadyExists) {
        // Add new song
        songs.add({
          'title': title,
          'path': path,
        });

        // Save back to storage
        final updatedJson = json.encode(songs);
        await prefs.setString('stored_songs', updatedJson);

        print(' Song saved: $title (${songs.length} total songs)');
      } else {
        print('ℹ️ Song already exists in storage: $title');
      }
    } catch (e) {
      print('❌ Error saving song: $e');
    }
  }

  // Play song from AllSongStoreScreen
  Future<void> _playSongFromStore(Map<String, String> song) async {
    try {
      final title = song['title'] ?? 'Unknown';
      final path = song['path'] ?? '';

      if (path.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('⚠️ Invalid song path'),
            backgroundColor: Colors.red,
            duration: Duration(seconds: 2),
          ),
        );
        return;
      }

      setState(() {
        _currentSongPath = path;
        _currentSongTitle = title;
      });

      await _audioPlayer?.setSourceDeviceFile(path);

      // Apply volume boost
      await Future.delayed(const Duration(milliseconds: 100));
      await _applyVolumeBoost(_volume);

      // Update current song index in the all songs list
      await _loadAllSongs(); // Reload to ensure we have latest list
      _currentSongIndex = _allSongs.indexWhere((s) => s['path'] == path);
      print(' Current song index updated to: $_currentSongIndex');

      // Auto-play the song
      await _audioPlayer?.resume();

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Row(
            children: [
              const Icon(Icons.play_circle_filled, color: Colors.white, size: 20),
              const SizedBox(width: 10),
              Expanded(
                child: Text(' Now playing: $title'),
              ),
            ],
          ),
          backgroundColor: Colors.cyan,
          duration: const Duration(seconds: 2),
        ),
      );

      print(' Playing from store: $title');
    } catch (e) {
      print('❌ Error playing song: $e');
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error playing song: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  String _formatDuration(Duration duration) {
    String twoDigits(int n) => n.toString().padLeft(2, '0');
    final minutes = twoDigits(duration.inMinutes.remainder(60));
    final seconds = twoDigits(duration.inSeconds.remainder(60));
    return '$minutes:$seconds';
  }
}

class VolumeRingPainter extends CustomPainter {
  final double volume;

  VolumeRingPainter(this.volume);

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final radius = size.width / 2;
    final strokeWidth = 12.0;

    // Draw colored segments
    final segmentCount = 48;
    final sweepAngle = (2 * math.pi) / segmentCount;

    for (int i = 0; i < segmentCount; i++) {
      final startAngle = -math.pi / 2 + (i * sweepAngle);

      Color segmentColor;
      final ratio = i / segmentCount;

      // Create smooth color transition: green -> lime -> yellow -> orange -> red
      if (ratio < 0.2) {
        segmentColor = const Color(0xFF00FF00); // Bright green
      } else if (ratio < 0.35) {
        segmentColor = const Color(0xFF7FFF00); // Lime green
      } else if (ratio < 0.5) {
        segmentColor = const Color(0xFFFFFF00); // Yellow
      } else if (ratio < 0.65) {
        segmentColor = const Color(0xFFFFD700); // Gold/Yellow-Orange
      } else if (ratio < 0.8) {
        segmentColor = const Color(0xFFFF8C00); // Orange
      } else {
        segmentColor = const Color(0xFFFF0000); // Red
      }

      // Determine if this segment should be lit based on volume
      final isActive = i < (volume / 200 * segmentCount);

      final paint = Paint()
        ..color = isActive ? segmentColor : Colors.grey[850]!
        ..style = PaintingStyle.stroke
        ..strokeWidth = strokeWidth
        ..strokeCap = StrokeCap.round;

      canvas.drawArc(
        Rect.fromCircle(center: center, radius: radius - strokeWidth / 2),
        startAngle,
        sweepAngle * 0.85, // Gap between segments
        false,
        paint,
      );
    }
  }

  @override
  bool shouldRepaint(VolumeRingPainter oldDelegate) {
    return oldDelegate.volume != volume;
  }
}
